import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), threshold = nextInt();
        // IDs have no leading zeros, so numeric order equals the required order.
        HashMap<Long, Integer> counts = new HashMap<>(4 * n);
        for (int i = 0; i < n; i++) {
            long a = nextLong(), b = nextLong();
            nextLong(); // amount does not matter
            counts.merge(a, 1, Integer::sum);
            if (b != a) counts.merge(b, 1, Integer::sum); // a self-transfer counts once
        }
        long[] result = counts.entrySet().stream().filter(e -> e.getValue() >= threshold).mapToLong(Map.Entry::getKey).toArray();
        Arrays.sort(result);
        StringBuilder sb = new StringBuilder().append(result.length).append('\n');
        for (long u : result) sb.append(u).append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, threshold := int(nextInt()), int(nextInt())
	// IDs have no leading zeros, so numeric order equals the required order.
	counts := make(map[int64]int, 2*n)
	for i := 0; i < n; i++ {
		a, b := nextInt(), nextInt()
		nextInt() // amount does not matter
		counts[a]++
		if b != a {
			counts[b]++ // a self-transfer counts once
		}
	}
	var result []int64
	for user, c := range counts {
		if c >= threshold {
			result = append(result, user)
		}
	}
	slices.Sort(result)
	out := strconv.AppendInt(nil, int64(len(result)), 10)
	out = append(out, '\n')
	for _, u := range result {
		out = strconv.AppendInt(out, u, 10)
		out = append(out, '\n')
	}
	os.Stdout.Write(out)
}
